#!/usr/bin/env python3
"""Generate rexuni.h — Unicode codepoint-range tables for REX's \\u
character classes (\\ualpha, \\udigit, \\umark, \\uspace, \\upunct and
the combinations \\ualnum, \\uword).

Usage:  python3 genrexuni.py UnicodeData.txt > rexuni.h

Classes are built from Unicode general categories:
    UALPHA  L*  (Lu Ll Lt Lm Lo)
    UDIGIT  Nd
    UMARK   M*  (Mn Mc Me)  -- combining marks; word-internal in every
                               serious tokenizer (Indic matras, Arabic
                               harakat, decomposed diacritics)
    USPACE  Zs
    UPUNCT  P* and S*
\\ualnum = UALPHA|UDIGIT and \\uword = UALPHA|UDIGIT|UMARK are just
combined mask bits at parse time; they need no tables of their own.

Only codepoints >= 0x80 are emitted: the ASCII portion of every class
lives in the normal REX byte set, so the byte-table fast path handles
ASCII and these tables are consulted only for multibyte sequences.

The generated header is checked in; regenerate only when adopting a new
Unicode version, and note the version in the commit.
"""
import sys

CLASSES = {
    "UALPHA": ("Lu", "Ll", "Lt", "Lm", "Lo"),
    "UDIGIT": ("Nd",),
    "UMARK":  ("Mn", "Mc", "Me"),
    "USPACE": ("Zs",),
    "UPUNCT": ("Pc", "Pd", "Ps", "Pe", "Pi", "Pf", "Po",
               "Sm", "Sc", "Sk", "So"),
}

def parse(path):
    """yield (codepoint_first, codepoint_last, category)"""
    pend = None
    with open(path, encoding="utf-8") as f:
        for line in f:
            parts = line.split(";")
            if len(parts) < 3:
                continue
            cp = int(parts[0], 16)
            name, cat = parts[1], parts[2]
            if name.endswith(", First>"):
                pend = (cp, cat)
                continue
            if name.endswith(", Last>"):
                assert pend and pend[1] == cat
                yield (pend[0], cp, cat)
                pend = None
                continue
            yield (cp, cp, cat)

def ranges_for(path, cats):
    out = []
    for lo, hi, cat in parse(path):
        if cat not in cats:
            continue
        if hi < 0x80:
            continue
        if lo < 0x80:
            lo = 0x80
        if out and lo == out[-1][1] + 1:
            out[-1] = (out[-1][0], hi)          # coalesce adjacent
        else:
            out.append((lo, hi))
    return out

def main():
    src = sys.argv[1]
    print("/* rexuni.h -- GENERATED by genrexuni.py; do not edit by hand.")
    print(" * Unicode codepoint-range tables for REX \\u character classes.")
    print(" * Regenerate: python3 genrexuni.py UnicodeData.txt > rexuni.h")
    print(" * (note the Unicode version in the commit when regenerating) */")
    print("#ifndef REXUNI_H")
    print("#define REXUNI_H")
    print()
    print("typedef struct { unsigned int lo, hi; } TXrexUniRange;")
    print()
    bits = []
    for i, (cname, cats) in enumerate(CLASSES.items()):
        r = ranges_for(src, cats)
        bits.append((cname, i, len(r)))
        print("#define TXREXUNI_%s (1 << %d)" % (cname, i))
        print("static const TXrexUniRange TXrexUni_%s[%d] = {" % (cname, len(r)))
        for j in range(0, len(r), 4):
            row = ", ".join("{0x%X,0x%X}" % p for p in r[j:j+4])
            print("  " + row + ("," if j + 4 < len(r) else ""))
        print("};")
        print()
    print("/* combined-class masks (no separate tables needed) */")
    print("#define TXREXUNI_UALNUM (TXREXUNI_UALPHA | TXREXUNI_UDIGIT)")
    print("#define TXREXUNI_UWORD  (TXREXUNI_UALPHA | TXREXUNI_UDIGIT | TXREXUNI_UMARK)")
    print("#define TXREXUNI_ALLMASK ((1 << %d) - 1)" % len(CLASSES))
    print()
    print("static const struct { const TXrexUniRange *r; int n; } TXrexUniTabs[%d] = {"
          % len(CLASSES))
    for cname, i, n in bits:
        print("  { TXrexUni_%s, %d }," % (cname, n))
    print("};")
    print("""
/* Is codepoint `cp' a member of any class in `mask'?  Binary search per
   set bit; tables cover only cp >= 0x80 (ASCII is handled by the REX
   byte sets). */
static int TXrexUniMember(unsigned int mask, unsigned int cp)
{
    int ci;
    for (ci = 0; mask; ci++, mask >>= 1)
    {
        const TXrexUniRange *r;
        int lo, hi;
        if (!(mask & 1)) continue;
        r = TXrexUniTabs[ci].r;
        lo = 0; hi = TXrexUniTabs[ci].n - 1;
        while (lo <= hi)
        {
            int mid = (lo + hi) / 2;
            if (cp < r[mid].lo) hi = mid - 1;
            else if (cp > r[mid].hi) lo = mid + 1;
            else return 1;
        }
    }
    return 0;
}

/* Decode one UTF-8 sequence at `p' (strictly: valid lead byte and the
   exact number of 0x80-0xBF continuation bytes, ending at or before
   `end').  Returns sequence length (2-4) and sets *cpOut, or 0 when the
   bytes do not form a valid multibyte sequence -- callers treat 0 as
   "not a member" (a natural word break, and safe on dirty data).
   ASCII bytes are the caller's fast path and never reach here. */
static int TXrexUniDecode(const unsigned char *p, const unsigned char *end,
                          unsigned int *cpOut)
{
    unsigned int cp;
    int n, i;
    unsigned char c = *p;
    if (c < 0xC2 || c > 0xF4) return 0;   /* not a lead (or overlong/oob) */
    if (c < 0xE0)      { n = 1; cp = c & 0x1F; }
    else if (c < 0xF0) { n = 2; cp = c & 0x0F; }
    else               { n = 3; cp = c & 0x07; }
    if (p + 1 + n > end) return 0;        /* truncated at buffer edge */
    for (i = 1; i <= n; i++)
    {
        if ((p[i] & 0xC0) != 0x80) return 0;
        cp = (cp << 6) | (p[i] & 0x3F);
    }
    *cpOut = cp;
    return n + 1;
}

#endif /* REXUNI_H */""")

main()
